PROFILE_CSS = "/* ─────────────────────────────────────────────\n   机构画像模块 (progress / quick)\n   风格对齐投资明细: 白底卡片 + 深蓝表头 + 搜索下拉\n   ───────────────────────────────────────────── */\n.prog-container {\n  max-width: 1280px; margin: 0 auto; padding: 24px 20px 40px;\n}\n.prog-ctrl-panel {\n  background: #fff; border-radius: 8px; padding: 20px 24px;\n  box-shadow: 0 1px 4px rgba(0,0,0,.08); margin-bottom: 20px;\n}\n.prog-ctrl-row {\n  display: flex; align-items: flex-end; gap: 16px; flex-wrap: wrap;\n}\n.prog-ctrl-group { display: flex; flex-direction: column; gap: 6px; flex: 1 1 280px; }\n.prog-ctrl-label {\n  font-size: 11px; color: #6b7a95; letter-spacing: 1px; text-transform: uppercase;\n}\n.prog-search-wrap { position: relative; width: 100%; }\n.prog-search-input {\n  height: 38px; border: 1px solid #d0d8e4; border-radius: 5px;\n  padding: 0 12px; font-size: 13px; font-family: inherit;\n  color: #1a1a2e; background: #fff; outline: none; transition: border-color .2s;\n  width: 100%; box-sizing: border-box;\n}\n.prog-search-input:focus { border-color: #2563a8; }\n.prog-search-dropdown {\n  display: none; position: absolute; top: 100%; left: 0; right: 0;\n  max-height: 320px; overflow-y: auto;\n  background: #fff; border: 1px solid #d0d8e4; border-top: none;\n  border-radius: 0 0 5px 5px; z-index: 200;\n  box-shadow: 0 4px 12px rgba(0,0,0,.12);\n}\n.prog-search-dropdown.show { display: block; }\n.prog-search-item {\n  padding: 9px 12px; font-size: 13px; color: #1a1a2e; cursor: pointer;\n  background: #fff; border-bottom: 1px solid #f0f4fa;\n  display: flex; justify-content: space-between; align-items: center; gap: 10px;\n}\n.prog-search-item:last-child { border-bottom: none; }\n.prog-search-item:hover, .prog-search-item.active {\n  background: #eef3fa; color: #0d1b2e;\n}\n.prog-search-item .psi-name { font-weight: 500; }\n.prog-search-item .psi-cat {\n  font-size: 11px; color: #6b7a95; background: #f0f4fa;\n  padding: 2px 8px; border-radius: 3px; white-space: nowrap;\n}\n.prog-search-empty {\n  padding: 12px; font-size: 12px; color: #9aa5b5; text-align: center;\n}\n.prog-stat-bar {\n  display: flex; gap: 12px; margin-top: 14px; flex-wrap: wrap;\n}\n.prog-stat-chip {\n  background: #f0f4fa; border-radius: 5px; padding: 6px 12px;\n  font-size: 12px; color: #2a4a7c;\n}\n.prog-stat-chip strong { color: #0d1b2e; font-weight: 700; margin-left: 4px; }\n\n/* 结果卡片 */\n.prog-result-area { display: none; }\n.prog-result-area.show { display: block; animation: fadeIn .3s ease; }\n.prog-hint-bar {\n  padding: 10px 16px; background: #e8f0fc; border-radius: 8px 8px 0 0;\n  font-size: 14px; color: #2a4a7c; display: flex;\n  justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 6px;\n}\n.prog-hint-bar strong { color: #1a3a5c; font-size: 15px; font-weight: 700; }\n.prog-hint-bar .prog-meta { font-size: 13px; color: #1a3a5c; font-weight: 600; }\n.prog-card-wrap {\n  background: #fff; border-radius: 0 0 8px 8px;\n  overflow: hidden; box-shadow: 0 1px 4px rgba(0,0,0,.07);\n}\n.prog-section {\n  padding: 14px 20px; border-bottom: 1px solid #eaeef4;\n}\n.prog-section:last-child { border-bottom: none; }\n.prog-section-title {\n  font-size: 13px; color: #1a3a5c; font-weight: 700; margin-bottom: 10px;\n  display: flex; align-items: center; gap: 8px;\n}\n.prog-section-title::before {\n  content: ''; display: inline-block; width: 3px; height: 14px;\n  background: #2563a8; border-radius: 2px;\n}\n.prog-info-grid {\n  display: grid; grid-template-columns: 1fr 1.8fr; gap: 1px;\n  background: #eaeef4;\n}\n.prog-info-cell {\n  background: #fff; padding: 14px 16px;\n}\n.prog-info-cell .pic-label {\n  font-size: 11px; color: #6b7a95; letter-spacing: 1px; text-transform: uppercase;\n  margin-bottom: 6px;\n}\n.prog-info-cell .pic-value {\n  font-size: 14px; color: #1a2a40; font-weight: 500; line-height: 1.5;\n  word-break: break-all;\n}\n.prog-info-cell .pic-value.cat-tag {\n  display: inline-block; background: #e8f0fc; color: #1a3a5c;\n  padding: 3px 10px; border-radius: 3px; font-size: 13px; font-weight: 600;\n}\n.prog-info-cell .pic-value.owner-tag {\n  display: inline-block; background: #2d7a4f; color: #fff;\n  padding: 3px 12px; border-radius: 3px; font-size: 13px; font-weight: 600;\n}\n.prog-info-cell .pic-value.contact-val {\n  font-size: 13px; color: #2a4a7c; white-space: pre-line;\n}\n/* 联系人结构化: 部门/职务 + 人名 (紧凑流式) */\n.prog-contact-list {\n  display: flex; flex-wrap: wrap; gap: 4px 6px;\n}\n.prog-contact-item {\n  display: inline-flex; align-items: center; gap: 4px;\n  padding: 2px 0;\n}\n.prog-contact-dept {\n  font-size: 10px; color: #6b7a95; background: #f0f4fa;\n  padding: 1px 5px; border-radius: 2px; white-space: nowrap;\n  max-width: 110px; overflow: hidden; text-overflow: ellipsis;\n}\n.prog-contact-name {\n  font-size: 12px; color: #1a2a40; font-weight: 500; white-space: nowrap;\n}\n/* 26年投资画像 */\n.prog-profile-tags {\n  display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px;\n}\n.prog-profile-tag {\n  display: inline-block; background: #e8f0fc; color: #1a3a5c;\n  padding: 3px 9px; border-radius: 3px; font-size: 12px; font-weight: 500;\n}\n.prog-profile-tag .ppt-num {\n  color: #2d7a4f; font-weight: 700; margin-left: 4px;\n}\n.prog-profile-tag.no-data {\n  background: #f5f7fa; color: #9aa5b5;\n}\n.prog-profile-credit {\n  display: flex; gap: 16px; margin-top: 8px; padding-top: 8px;\n  border-top: 1px dashed #d0d8e4; flex-wrap: wrap;\n}\n.prog-profile-credit-item {\n  font-size: 12px; color: #4a5a75;\n}\n.prog-profile-credit-item .label {\n  color: #6b7a95; margin-right: 4px;\n}\n.prog-profile-credit-item .val {\n  color: #1a3a5c; font-weight: 700; font-variant-numeric: tabular-nums;\n}\n.prog-profile-credit-item .val.dyn {\n  color: #2d7a4f;\n}\n.prog-profile-source {\n  font-size: 10px; color: #9aa5b5; margin-top: 6px; font-style: italic;\n}\n/* 投资画像年度表格 */\n.prog-profile-years {\n  display: flex; flex-direction: column; gap: 10px;\n}\n.prog-profile-year-block {\n  border: 1px solid #eaeef4; border-radius: 5px; overflow: hidden;\n}\n.prog-profile-year-head {\n  display: flex; justify-content: space-between; align-items: center;\n  padding: 6px 10px; background: #f0f4fa;\n}\n.prog-profile-year-title {\n  font-size: 12px; font-weight: 700; color: #1a3a5c;\n}\n.prog-profile-year-total {\n  font-size: 11px; color: #4a5a75;\n}\n.prog-profile-year-total .yt-num {\n  color: #2d7a4f; font-weight: 700; font-variant-numeric: tabular-nums; margin: 0 4px;\n}\n.prog-profile-table {\n  width: 100%; border-collapse: collapse; table-layout: fixed;\n}\n.prog-profile-table th {\n  background: #fafbfc; color: #6b7a95; font-size: 10px; font-weight: 600;\n  padding: 4px 8px; text-align: left; border-bottom: 1px solid #eaeef4;\n  letter-spacing: .5px;\n}\n.prog-profile-table th.num-col { text-align: right; }\n.prog-profile-table td {\n  padding: 4px 8px; font-size: 11px; border-bottom: 1px solid #f0f4fa;\n  font-variant-numeric: tabular-nums;\n}\n.prog-profile-table td.asset-name { color: #1a2a40; }\n.prog-profile-table td.num-val { text-align: right; color: #1a3a5c; font-weight: 600; }\n.prog-profile-table td.pct-val { text-align: right; color: #6b7a95; }\n.prog-profile-table td.spread-val { text-align: right; color: #2d7a4f; }\n.prog-profile-table tr:last-child td { border-bottom: none; }\n.prog-profile-table tr.total-row td {\n  background: #f5f8fc; font-weight: 700; border-top: 1px solid #d0d8e4;\n}\n.prog-profile-empty {\n  padding: 12px; font-size: 11px; color: #9aa5b5; text-align: center;\n}\n.prog-progress-section {\n  background: #fff; padding: 16px 20px; border-top: 1px solid #eaeef4;\n}\n.prog-progress-title {\n  font-size: 13px; color: #1a3a5c; font-weight: 700; margin-bottom: 12px;\n  display: flex; align-items: center; gap: 8px;\n}\n.prog-progress-title::before {\n  content: ''; display: inline-block; width: 3px; height: 14px;\n  background: #2563a8; border-radius: 2px;\n}\n.prog-progress-list {\n  display: flex; flex-direction: column; gap: 10px;\n}\n.prog-progress-item {\n  display: flex; gap: 14px; padding: 10px 14px;\n  background: #fafbfc; border-left: 3px solid #2563a8; border-radius: 0 5px 5px 0;\n}\n.prog-progress-item:nth-child(even) {\n  background: #f5f8fc;\n}\n.prog-progress-date {\n  flex-shrink: 0; width: 96px; font-size: 12px; font-weight: 700;\n  color: #2563a8; font-variant-numeric: tabular-nums;\n  padding-top: 1px;\n}\n.prog-progress-text {\n  flex: 1; font-size: 13px; color: #2a3548; line-height: 1.6;\n  word-break: break-all;\n}\n.prog-empty-state {\n  background: #fff; border-radius: 8px; padding: 40px;\n  text-align: center; color: #8a9ab5; font-size: 13px;\n  box-shadow: 0 1px 4px rgba(0,0,0,.07);\n}\n.prog-empty-state .pe-title { font-size: 15px; color: #1a3a5c; font-weight: 600; margin-bottom: 6px; }\n.prog-footer {\n  margin-top: 16px; padding: 10px 16px; font-size: 11px; color: #8a9ab5;\n  text-align: right; line-height: 1.6;\n}\n"

_BODY_HTML = '<div class="tool-banner">\n  <div class="banner-tag">ABS Institution Progress Overview · LAB v1</div>\n  <div class="banner-title">机构画像</div>\n  <div class="banner-sub">输入机构关键词速查 · 机构类型 / 负责人 / 联系人 / 最新5条进展记录</div>\n</div>\n\n<div class="prog-container">\n  <div class="prog-ctrl-panel">\n    <div class="prog-ctrl-row">\n      <div class="prog-ctrl-group">\n        <div class="prog-ctrl-label">机构名称搜索</div>\n        <div class="prog-search-wrap">\n          <input type="text" id="progInstSelect" class="prog-search-input"\n                 placeholder="输入关键词搜索机构（如：建行、易方达、信托）" autocomplete="off">\n          <div class="prog-search-dropdown" id="progInstDropdown"></div>\n        </div>\n      </div>\n      <div class="prog-ctrl-group" style="flex: 0 0 160px;">\n        <div class="prog-ctrl-label">负责人</div>\n        <select id="progOwnerFilter" class="invest-select" onchange="progRenderDropdown(document.getElementById(\'progInstSelect\').value)">\n          <option value="">全部</option>\n          <option value="吴沛智">吴沛智</option>\n          <option value="李亦非">李亦非</option>\n          <option value="姜守园">姜守园</option>\n          <option value="邓殷洁">邓殷洁</option>\n          <option value="高雅">高雅</option>\n        </select>\n      </div>\n      <div class="prog-ctrl-group" style="flex: 0 0 180px;">\n        <div class="prog-ctrl-label">机构类型</div>\n        <select id="progCategoryFilter" class="invest-select" onchange="progRenderDropdown(document.getElementById(\'progInstSelect\').value)">\n          <option value="">全部</option>\n        </select>\n      </div>\n    </div>\n  </div>\n\n  <div class="prog-result-area" id="progResultArea">\n    <div class="prog-hint-bar">\n      <span id="progHintText"></span>\n      <span class="prog-meta" id="progMetaTag"></span>\n    </div>\n    <div class="prog-card-wrap">\n      <div class="prog-section" id="progContactSection"></div>\n      <div class="prog-section" id="progProgressSection"></div>\n      <div class="prog-section" id="progCreditSection"></div>\n      <div class="prog-section" id="progProfileSection"></div>\n    </div>\n  </div>\n\n  <div class="prog-empty-state" id="progEmptyState">\n    <div class="pe-title">输入机构名称开始查询</div>\n    <div>支持模糊搜索 · 从搜索结果下拉列表中选择机构查看详情</div>\n  </div>\n\n  <div class="prog-footer">\n    数据来源：JoySpace「2026年ABS管理人与投资人进展表」吴沛智 sheet · 快照时间 2026-07-14 ·\n    负责人：吴沛智 · 分析报告员 Peizhi Wu\n  </div>\n</div>\n\n'

_PROFILE_JS_TEMPLATE = '// === 机构画像：数据与交互 ===\nconst PROG_ALL_DATA = __PROG_ALL_DATA__;\n\nlet PROG_ACTIVE_IDX = -1;\n\nfunction progInit() {\n  const input = document.getElementById(\'progInstSelect\');\n  const dropdown = document.getElementById(\'progInstDropdown\');\n  if (!input || !dropdown) return;\n\n  input.addEventListener(\'focus\', function() {\n    progRenderDropdown(\'\');\n    dropdown.classList.add(\'show\');\n  });\n  input.addEventListener(\'input\', function() {\n    progRenderDropdown(this.value);\n    dropdown.classList.add(\'show\');\n    PROG_ACTIVE_IDX = -1;\n  });\n  input.addEventListener(\'keydown\', function(e) {\n    const items = dropdown.querySelectorAll(\'.prog-search-item\');\n    if (e.key === \'ArrowDown\') {\n      e.preventDefault();\n      PROG_ACTIVE_IDX = Math.min(PROG_ACTIVE_IDX + 1, items.length - 1);\n      progUpdateActive(items);\n    } else if (e.key === \'ArrowUp\') {\n      e.preventDefault();\n      PROG_ACTIVE_IDX = Math.max(PROG_ACTIVE_IDX - 1, 0);\n      progUpdateActive(items);\n    } else if (e.key === \'Enter\') {\n      e.preventDefault();\n      if (PROG_ACTIVE_IDX >= 0 && items[PROG_ACTIVE_IDX]) items[PROG_ACTIVE_IDX].click();\n    } else if (e.key === \'Escape\') {\n      dropdown.classList.remove(\'show\');\n    }\n  });\n  document.addEventListener(\'click\', function(e) {\n    if (!e.target.closest(\'.prog-search-wrap\')) dropdown.classList.remove(\'show\');\n  });\n\n  // 填充机构类型下拉\n  const catSel = document.getElementById(\'progCategoryFilter\');\n  if (catSel) {\n    const catList = [...new Set(PROG_ALL_DATA.map(r => r.category))].sort();\n    catSel.innerHTML = \'<option value="">全部</option>\' +\n      catList.map(c => \'<option value="\' + c + \'">\' + c + \'</option>\').join(\'\');\n  }\n}\n\nfunction progGetFiltered() {\n  const owner = document.getElementById(\'progOwnerFilter\') ? document.getElementById(\'progOwnerFilter\').value : \'\';\n  const cat = document.getElementById(\'progCategoryFilter\') ? document.getElementById(\'progCategoryFilter\').value : \'\';\n  return PROG_ALL_DATA.filter(r =>\n    (!owner || r.owner === owner) && (!cat || r.category === cat)\n  );\n}\n\nfunction progRenderDropdown(query) {\n  const dropdown = document.getElementById(\'progInstDropdown\');\n  if (!dropdown) return;\n  const q = (query || \'\').trim().toLowerCase();\n  let filtered = progGetFiltered();\n  if (q) {\n    filtered = filtered.filter(r =>\n      r.name.toLowerCase().includes(q) ||\n      (r.category || \'\').toLowerCase().includes(q) ||\n      (r.contact || \'\').toLowerCase().includes(q) ||\n      (r.owner || \'\').toLowerCase().includes(q)\n    );\n  }\n  if (filtered.length === 0) {\n    dropdown.innerHTML = \'<div class="prog-search-empty">未找到匹配机构</div>\';\n    return;\n  }\n  dropdown.innerHTML = filtered.map((r, idx) => {\n    return \'<div class="prog-search-item" data-idx="\' + idx + \'" data-name="\' + r.name + \'" data-owner="\' + r.owner + \'">\' +\n      \'<span class="psi-name">\' + r.name + \'</span>\' +\n      \'<span class="psi-cat">\' + r.owner + \' · \' + r.category + \'</span>\' +\n      \'</div>\';\n  }).join(\'\');\n  // 保存当前筛选后的列表供点击定位\n  window.__progFiltered = filtered;\n  dropdown.querySelectorAll(\'.prog-search-item\').forEach(item => {\n    item.addEventListener(\'click\', function() {\n      const name = this.dataset.name;\n      const owner = this.dataset.owner;\n      document.getElementById(\'progInstSelect\').value = name;\n      dropdown.classList.remove(\'show\');\n      progDoSearch(name, owner);\n    });\n  });\n}\n\nfunction progUpdateActive(items) {\n  items.forEach((item, idx) => {\n    item.classList.toggle(\'active\', idx === PROG_ACTIVE_IDX);\n    if (idx === PROG_ACTIVE_IDX) item.scrollIntoView({ block: \'nearest\' });\n  });\n}\n\nfunction progDoSearch(name, owner) {\n  const resultArea = document.getElementById(\'progResultArea\');\n  const emptyState = document.getElementById(\'progEmptyState\');\n  const hintText = document.getElementById(\'progHintText\');\n  const metaTag = document.getElementById(\'progMetaTag\');\n\n  let rec;\n  if (owner) {\n    rec = PROG_ALL_DATA.find(r => r.name === name && r.owner === owner);\n  }\n  if (!rec) {\n    rec = PROG_ALL_DATA.find(r => r.name === name);\n  }\n  if (!rec) {\n    resultArea.classList.remove(\'show\');\n    emptyState.style.display = \'block\';\n    emptyState.querySelector(\'.pe-title\').textContent = \'未找到该机构\';\n    return;\n  }\n\n  emptyState.style.display = \'none\';\n  resultArea.classList.add(\'show\');\n\n  hintText.innerHTML = \'<strong>\' + rec.name + \'</strong><span style="font-size:12px;color:#6b7a95;font-weight:500;margin-left:10px;background:#f0f4fa;padding:3px 10px;border-radius:3px">\' + rec.owner + \'</span>\';\n  metaTag.textContent = \'共 \' + rec.progress_count + \' 条进展记录\';\n\n  const contact = rec.contact || \'—\';\n  const contactSection = document.getElementById(\'progContactSection\');\n  const progressSection = document.getElementById(\'progProgressSection\');\n  const creditSection = document.getElementById(\'progCreditSection\');\n  const profileSection = document.getElementById(\'progProfileSection\');\n\n  // 1. 联系人信息\n  contactSection.innerHTML = \'<div class="prog-section-title">联系人信息</div>\' + progRenderContact(contact);\n\n  // 2. 最近5条进展记录\n  if (rec.recent_progress.length === 0) {\n    progressSection.innerHTML = \'<div class="prog-section-title">最近进展记录</div>\' +\n      \'<div style="padding:20px;color:#9aa5b5;font-size:13px;text-align:center">暂无进展记录</div>\';\n  } else {\n    const dateRange = rec.recent_progress[0].date + \' → \' + rec.recent_progress[rec.recent_progress.length - 1].date;\n    let html = \'<div class="prog-section-title">最近 \' + rec.recent_progress.length + \' 条进展记录 <span style="font-size:12px;color:#6b7a95;font-weight:400">（\' + dateRange + \'）</span></div>\';\n    html += \'<div class="prog-progress-list">\';\n    rec.recent_progress.forEach(p => {\n      html += \'<div class="prog-progress-item">\' +\n        \'<div class="prog-progress-date">\' + p.date + \'</div>\' +\n        \'<div class="prog-progress-text">\' + progEsc(p.text) + \'</div>\' +\n        \'</div>\';\n    });\n    html += \'</div>\';\n    progressSection.innerHTML = html;\n  }\n\n  // 3. 授信统计\n  creditSection.innerHTML = \'<div class="prog-section-title">授信统计</div>\' + progBuildCredit(rec);\n\n  // 4. 各年投资画像\n  profileSection.innerHTML = \'<div class="prog-section-title">各年投资画像 <span style="font-size:10px;color:#9aa5b5;font-weight:400">（联动投资台账实时计算）</span></div>\' + progBuildProfile(rec);\n}\n\n// === 联系人结构化解析: 部门/职务 + 人名 ===\n// 解析单个联系人片段,返回 {dept, name}\nfunction progParseContact(seg) {\n  seg = seg.trim();\n  if (!seg) return null;\n  // 去掉前后分号和空格\n  seg = seg.replace(/^[;、，,\\s]+|[;、，,\\s]+$/g, \'\');\n  if (!seg) return null;\n\n  // 模式1: 人名（部门） 如 "张志勇（北分总）"\n  let m = seg.match(/^([一-龥·]{2,5})[（(]([^）)]*)[）)]$/);\n  if (m) return { dept: m[2], name: m[1] };\n\n  // 模式2: 部门-人名 如 "总牵头-张佳乐" 或 "余俊琴-投行ED(bj)"\n  if (seg.indexOf(\'-\') >= 0 || seg.indexOf(\'—\') >= 0) {\n    const parts = seg.split(/[-—]/);\n    if (parts.length >= 2) {\n      const left = parts[0].trim();\n      const right = parts.slice(1).join(\'-\').trim();\n      // 判断哪边是人名(2-5个中文字符)\n      const leftIsName = /^[一-龥·]{2,5}$/.test(left);\n      const rightIsName = /^[一-龥·]{2,5}$/.test(right);\n      if (leftIsName && !rightIsName) return { dept: right, name: left };\n      if (rightIsName && !leftIsName) return { dept: left, name: right };\n      // 两边都不像纯人名,取短的是部门,长的是人名+其他\n      if (leftIsName) return { dept: right, name: left };\n      if (rightIsName) return { dept: left, name: right };\n      // 都不是纯人名(可能含英文),按位置:左边部门,右边人名\n      return { dept: left, name: right };\n    }\n  }\n\n  // 模式3: 部门人名 如 "固收部陶健" (部门在前,人名2-5字在后)\n  m = seg.match(/^([一-龥A-Za-z]{2,10}?)([一-龥·]{2,5})$/);\n  if (m && m[1].length >= 2) return { dept: m[1], name: m[2] };\n\n  // 模式4: 纯人名(2-5字) 无部门\n  if (/^[一-龥·]{2,5}$/.test(seg)) return { dept: \'\', name: seg };\n\n  // 兜底:整段当人名(可能含英文/数字)\n  return { dept: \'\', name: seg };\n}\n\n// 解析整个联系人字段,返回结构化列表\nfunction progParseContacts(contactStr) {\n  if (!contactStr || contactStr === \'—\') return [];\n  // 按 ; 或 \\n 拆成段\n  const segs = contactStr.replace(/\\\\n/g, \';\').split(/[;\\n]/);\n  const result = [];\n  segs.forEach(seg => {\n    seg = seg.trim();\n    if (!seg) return;\n    // 段内可能还有顿号分隔的多人(如"DCM-李俊润、原静雯")\n    // 如果段内有"-"或"—",且顿号在右边,拆成多人同部门\n    const dashMatch = seg.match(/^(.+?[-—])(.+)$/);\n    if (dashMatch) {\n      const deptPart = dashMatch[1].replace(/[-—]$/, \'\').trim();\n      const namesPart = dashMatch[2].trim();\n      // 顿号拆多人\n      const names = namesPart.split(/[、,，]/).map(s => s.trim()).filter(Boolean);\n      if (names.length > 1) {\n        names.forEach(n => {\n          const parsed = progParseContact(n);\n          if (parsed) result.push({ dept: deptPart, name: parsed.name || n });\n        });\n        return;\n      }\n    }\n    // 顿号连接的纯人名(无部门),各自解析\n    if (seg.indexOf(\'、\') >= 0 && seg.indexOf(\'-\') < 0 && seg.indexOf(\'—\') < 0 && seg.indexOf(\'（\') < 0) {\n      const names = seg.split(/[、,，]/).map(s => s.trim()).filter(Boolean);\n      // 检查是否都是纯人名\n      const allNames = names.every(n => /^[一-龥·]{2,5}$/.test(n));\n      if (allNames) {\n        names.forEach(n => result.push({ dept: \'\', name: n }));\n        return;\n      }\n    }\n    const parsed = progParseContact(seg);\n    if (parsed) result.push(parsed);\n  });\n  return result;\n}\n\n// 渲染联系人结构化HTML\nfunction progRenderContact(contactStr) {\n  const contacts = progParseContacts(contactStr);\n  if (contacts.length === 0) {\n    return \'<span style="color:#9aa5b5">—</span>\';\n  }\n  return \'<div class="prog-contact-list">\' + contacts.map(c => {\n    const deptHtml = c.dept ? \'<span class="prog-contact-dept">\' + progEsc(c.dept) + \'</span>\' : \'\';\n    return \'<div class="prog-contact-item">\' + deptHtml + \'<span class="prog-contact-name">\' + progEsc(c.name) + \'</span></div>\';\n  }).join(\'\') + \'</div>\';\n}\n\n// === 26年投资画像：联动投资台账 + 授信模块 + joyspace兜底 ===\n\n// 授信总额度数据（从授信总额度模块提取，18家基石投资人）\nconst PROG_CREDIT_DATA = {\n  "北银理财": {total: 20.0, remain: 14.0},\n  "工银理财": {total: 165.0, remain: 27.5},\n  "东莞农商业银行": {total: 12.0, remain: 11.0},\n  "光大理财": {total: 30.0, remain: 15.0},\n  "广银理财": {total: 50.0, remain: 20.0},\n  "广州银行": {total: 20.0, remain: 15.0},\n  "杭银理财": {total: 14.0, remain: 3.0},\n  "杭州联合银行": {total: 10.0, remain: 5.9},\n  "恒丰银行": {total: 6.0, remain: 3.0},\n  "沪农商行": {total: 40.0, remain: 26.8},\n  "华夏理财": {total: 80.0, remain: 60.0},\n  "建设银行": {total: 60.0, remain: 56.0},\n  "建信理财": {total: 50.0, remain: 24.0},\n  "江苏银行": {total: 54.0, remain: 14.2},\n  "交银理财": {total: 300.0, remain: 183.0},\n  "民生理财": {total: 80.0, remain: 20.0},\n  "南京银行": {total: 70.0, remain: 20.0},\n  "南银理财": {total: 150.0, remain: 10.0},\n};\n\n// 机构进展名 → 台账机构名（列表）的映射\n// 规则:带后缀的精确匹配,不带后缀的匹配所有同名变体\n// 用户指定: (投行)和(自营)不是同一家,各自独立\nconst PROG_NAME_MAP = {\n  // 建投系列: 进展名"建投：XX" → 台账"中信建投XX"\n  "建投：衍生品": ["中信建投衍生品", "中信建投衍生品（自营）", "中信建投（衍生品）", "中信建投（衍生品部）", "中信建投-衍生品"],\n  "建投：投顾": ["中信建投衍生品（投顾）", "中信建投（投顾）"],\n  "建投：机构部": ["中信建投机构部", "中信建投（机构部）"],\n  "建投：资管": ["中信建投证券", "中信建投"],\n  "中信建投": ["中信建投", "中信建投（投行）"],\n  // 中信证券系列\n  "中信证券:自营、资管、投顾、财富": ["中信证券（自营）", "中信证券（资管）", "中信证券（投顾）", "中信证券（投行）", "中信证券", "中信（投顾）"],\n  "中信证券": ["中信证券", "中信证券（投行）", "中信证券（投顾）", "中信证券（自营）"],\n  // 国泰海通\n  "国泰海通": ["国泰海通", "国泰海通（投行）", "国泰海通（自营）", "国泰海通（资管）"],\n  "国泰海通：自营、资管": ["国泰海通（自营）", "国泰海通（资管）"],\n  // 华泰\n  "华泰资管": ["华泰资管", "华泰证券（资管）", "华泰证券"],\n  "华泰证券:资管、金融产品部": ["华泰证券（资管）", "华泰证券"],\n  // 中金\n  "中金：自营、投顾、资管、中金财富": ["中金公司", "中金（自营）", "中金（投顾）", "中金（资管）", "中金财富", "中金"],\n  // 广发\n  "广发证券": ["广发证券", "广发证券（自营）", "广发证券（资管）"],\n  "广发资管": ["广发资管", "广发证券（资管）"],\n  // 招商\n  "招商证券": ["招商证券", "招商证券（投行）", "招商证券（自营）", "招商证券（资管）"],\n  "招商证券：自营、资管、期货": ["招商证券（自营）", "招商证券（资管）", "招商期货"],\n  // 兴业\n  "兴业证券": ["兴业证券", "兴业证券（投行）", "兴业证券（自营）"],\n  "兴业证券:自营、资管": ["兴业证券（自营）", "兴业证券（资管）"],\n  // 其他券商带后缀的\n  "国信证券自营": ["国信证券（自营）", "国信证券"],\n  "国信证券": ["国信证券", "国信证券（投行）", "国信证券（自营）"],\n  "天风自营": ["天风证券（自营）", "天风资管", "天风证券"],\n  "申万宏源": ["申万宏源", "申万宏源（投行）", "申万宏源（自营）", "申万宏源（投顾）"],\n  "申万宏源:自营、汇智": ["申万宏源（自营）", "申万宏源（投顾）"],\n  "浙商证券自营": ["浙商证券（自营）", "浙商证券"],\n  "银河证券": ["银河证券", "中国银河", "银河证券（投行）"],\n  "银河证券：FICC、固收": ["银河证券（FICC）", "银河证券"],\n  "华兴证券：自营": ["华兴证券（自营）", "华兴证券"],\n  "信达证券：自营": ["信达证券（自营）", "信达证券"],\n  "西部证券": ["西部证券", "西部证券（投行）"],\n  "西部证券：自营": ["西部证券（自营）", "西部证券"],\n  "中泰证券：自营、资管": ["中泰证券（自营）", "中泰证券（资管）", "中泰证券"],\n  "华宝证券：自营、资管": ["华宝证券（自营）", "华宝证券（资管）", "华宝证券"],\n  "国投证券：自营、资管": ["国投证券（自营）", "国投证券（资管）", "国投证券", "国投资管"],\n  "国元证券：自营": ["国元证券（自营）", "国元证券"],\n  "野村东方证券：自营": ["野村东方证券（自营）", "野村东方证券"],\n  "财通证券:自营": ["财通证券（自营）", "财通资管", "财通证券"],\n  "东证融汇": ["东证融汇", "东方证券（资管）"],\n  "国联民生证券:资管": ["国联证券（资管）", "国联证券", "国联民生"],\n};\n\n// 台账数据缓存(启动时从 ITL_DATA_2026 聚合)\nlet PROG_LEDGER_PROFILE = null;\n\n// 优先档白名单(与发行定价·利差分析tab同步: 仅统计优先A/优先级/优先A1/优先A2)\nconst PROG_PRIORITY_LAYERS = [\'优先A\', \'优先级\', \'优先A1\', \'优先A2\', \'优先A档\'];\n\nfunction progBuildLedgerProfile() {\n  if (PROG_LEDGER_PROFILE) return PROG_LEDGER_PROFILE;\n  PROG_LEDGER_PROFILE = {};\n  if (typeof ITL_ALL_DATA === \'undefined\' && typeof ITL_DATA_2026 === \'undefined\') return PROG_LEDGER_PROFILE;\n  const ledger = typeof ITL_ALL_DATA !== \'undefined\' ? ITL_ALL_DATA : ITL_DATA_2026;\n  // 结构: {inst: {year: {asset: {share, spreadSum, spreadCount, details[]}}}}\n  // share 统计所有档位; spread 只统计优先档(与利差分析tab一致); details 保留项目级投资明细\n  ledger.forEach(r => {\n    const inst = r.inst;\n    if (!inst) return;\n    const share = parseFloat(r.share) || 0;\n    const asset = progNormalizeAsset(r.asset || \'未知\');\n    const year = r.year || \'未知\';\n    const layer = r.layer || \'\';\n    const isPriority = PROG_PRIORITY_LAYERS.indexOf(layer) >= 0;\n    const spread = (isPriority && r.spread != null) ? parseFloat(r.spread) : null;\n    if (!PROG_LEDGER_PROFILE[inst]) PROG_LEDGER_PROFILE[inst] = {};\n    if (!PROG_LEDGER_PROFILE[inst][year]) PROG_LEDGER_PROFILE[inst][year] = {};\n    if (!PROG_LEDGER_PROFILE[inst][year][asset]) PROG_LEDGER_PROFILE[inst][year][asset] = {share: 0, spreadSum: 0, spreadCount: 0, details: []};\n    PROG_LEDGER_PROFILE[inst][year][asset].share += share;\n    PROG_LEDGER_PROFILE[inst][year][asset].details.push({\n      date: r.date || \'\',\n      project: r.proj || r.project || \'\',\n      asset: asset,\n      layer: layer,\n      share: share,\n      cost: r.cost != null ? parseFloat(r.cost) : null,\n      spread: spread\n    });\n    if (spread != null && !isNaN(spread)) {\n      PROG_LEDGER_PROFILE[inst][year][asset].spreadSum += spread * share;\n      PROG_LEDGER_PROFILE[inst][year][asset].spreadCount += share;\n    }\n  });\n  return PROG_LEDGER_PROFILE;\n}\n\n// 资产类型归一化(去期限,粗粒度)\nfunction progNormalizeAsset(asset) {\n  if (!asset) return \'未知\';\n  // 已经是粗粒度的直接返回\n  const coarse = [\'赊销白条\', \'白条取现\', \'信托白条\', \'信托金条\', \'信托白取\', \'金条&白取混发\', \'金条&白取&白条混发\', \'金条&白取&信托白条混发\', \'保理\', \'信托企业主贷\', \'小贷企业主贷\', \'京企贷\', \'动产质押\', \'汽车融资租赁\', \'金采\'];\n  if (coarse.includes(asset)) return asset;\n  return asset;\n}\n\n// 根据机构进展名,找到台账里对应的机构名列表\n// 单个机构名 → 台账机构名列表(内部函数)\nfunction progResolveSingle(progName, profile) {\n  // 1. 精确映射表\n  if (PROG_NAME_MAP[progName]) return PROG_NAME_MAP[progName];\n  // 2. 自动匹配:去掉进展名里的冒号后缀,用包含关系匹配台账\n  const baseName = progName.split(\':\')[0].split(\'：\')[0].replace(/（.*?）/g, \'\').replace(/\\(.*?\\)/g, \'\').trim();\n  if (!baseName) return [];\n  const matches = Object.keys(profile).filter(inst => {\n    const instBase = inst.replace(/（.*?）/g, \'\').replace(/\\(.*?\\)/g, \'\').replace(/-.*$/, \'\').trim();\n    return instBase === baseName || inst === progName || inst.indexOf(baseName) === 0;\n  });\n  return matches.length > 0 ? matches : [baseName];\n}\n\nfunction progResolveLedgerNames(progName) {\n  const profile = progBuildLedgerProfile();\n  // 智能拆分 "/" 前后两个机构(如"交通银行/交银理财"),各自匹配后合并去重\n  // 注意:只拆分顶层 "/",不拆分括号内的\n  const parts = progName.split(\'/\').map(s => s.trim()).filter(Boolean);\n  if (parts.length <= 1) {\n    return progResolveSingle(progName, profile);\n  }\n  // 多部分:各自解析,合并去重\n  const all = new Set();\n  parts.forEach(p => {\n    progResolveSingle(p, profile).forEach(n => all.add(n));\n  });\n  return Array.from(all);\n}\n\n// 构建某机构的投资画像HTML(按年度表格,利差仅统计优先档)\nfunction progBuildProfile(rec) {\n  const profile = progBuildLedgerProfile();\n  const ledgerNames = progResolveLedgerNames(rec.name);\n\n  const yearAgg = {};\n  const yearTotal = {};\n  let hasAnyData = false;\n  ledgerNames.forEach(ln => {\n    if (profile[ln]) {\n      Object.keys(profile[ln]).forEach(year => {\n        if (!yearAgg[year]) { yearAgg[year] = {}; yearTotal[year] = 0; }\n        Object.keys(profile[ln][year]).forEach(asset => {\n          const d = profile[ln][year][asset];\n          if (!yearAgg[year][asset]) yearAgg[year][asset] = {share: 0, spreadSum: 0, spreadCount: 0, details: []};\n          yearAgg[year][asset].share += d.share;\n          yearAgg[year][asset].spreadSum += d.spreadSum;\n          yearAgg[year][asset].spreadCount += d.spreadCount;\n          yearAgg[year][asset].details = yearAgg[year][asset].details.concat(d.details || []);\n          yearTotal[year] += d.share;\n          if (d.share > 0) hasAnyData = true;\n        });\n      });\n    }\n  });\n\n  const years = Object.keys(yearAgg).sort().reverse();\n  let yearsHtml = \'\';\n  if (hasAnyData && years.length > 0) {\n    yearsHtml = \'<div class="prog-profile-years">\';\n    years.forEach(year => {\n      const total = yearTotal[year] || 0;\n      const assets = Object.entries(yearAgg[year]).sort((a, b) => b[1].share - a[1].share);\n      let rowsHtml = \'\';\n      let yearSpreadSum = 0, yearSpreadCnt = 0;\n      assets.forEach(([asset, d]) => {\n        const pct = total > 0 ? (d.share / total * 100) : 0;\n        const avgSpread = d.spreadCount > 0 ? (d.spreadSum / d.spreadCount) : null;\n        yearSpreadSum += d.spreadSum;\n        yearSpreadCnt += d.spreadCount;\n        rowsHtml += \'<tr>\' +\n          \'<td class="asset-name">\' + progEsc(asset) + \'</td>\' +\n          \'<td class="num-val">\' + d.share.toFixed(2) + \'</td>\' +\n          \'<td class="pct-val">\' + pct.toFixed(1) + \'%</td>\' +\n          \'<td class="spread-val">\' + (avgSpread != null ? (avgSpread * 10000).toFixed(0) + \'bp\' : \'—\') + \'</td>\' +\n          \'</tr>\';\n      });\n      const yearAvgSpread = yearSpreadCnt > 0 ? (yearSpreadSum / yearSpreadCnt) : null;\n      rowsHtml += \'<tr class="total-row">\' +\n        \'<td class="asset-name">合计</td>\' +\n        \'<td class="num-val">\' + total.toFixed(2) + \'</td>\' +\n        \'<td class="pct-val">100.0%</td>\' +\n        \'<td class="spread-val">\' + (yearAvgSpread != null ? (yearAvgSpread * 10000).toFixed(0) + \'bp\' : \'—\') + \'</td>\' +\n        \'</tr>\';\n      const detailRows = assets.flatMap(([asset, d]) => (d.details || []).map(x => Object.assign({}, x, {asset: asset})))\n        .sort((a, b) => String(b.date || \'\').localeCompare(String(a.date || \'\')) || (b.share || 0) - (a.share || 0));\n      let detailRowsHtml = \'\';\n      detailRows.forEach(d => {\n        detailRowsHtml += \'<tr>\' +\n          \'<td class="asset-name">\' + progEsc(d.date || \'—\') + \'</td>\' +\n          \'<td class="asset-name">\' + progEsc(d.project || \'—\') + \'</td>\' +\n          \'<td class="asset-name">\' + progEsc(d.asset || \'—\') + \'</td>\' +\n          \'<td class="asset-name">\' + progEsc(d.layer || \'—\') + \'</td>\' +\n          \'<td class="num-val">\' + (d.share || 0).toFixed(2) + \'</td>\' +\n          \'<td class="num-val">\' + (d.cost != null && !isNaN(d.cost) ? d.cost.toFixed(4) : \'—\') + \'</td>\' +\n          \'<td class="spread-val">\' + (d.spread != null && !isNaN(d.spread) ? (d.spread * 10000).toFixed(0) + \'bp\' : \'—\') + \'</td>\' +\n          \'</tr>\';\n      });\n      const detailTable = detailRowsHtml ? (\n        \'<div class="prog-profile-detail-title">投资明细（项目级）</div>\' +\n        \'<table class="prog-profile-table prog-profile-detail-table">\' +\n          \'<thead><tr><th>日期</th><th>项目</th><th>资产类型</th><th>分层</th><th class="num-col">规模(亿)</th><th class="num-col">成本</th><th class="num-col">利差</th></tr></thead>\' +\n          \'<tbody>\' + detailRowsHtml + \'</tbody>\' +\n        \'</table>\') : \'\';\n      yearsHtml += \'<div class="prog-profile-year-block">\' +\n        \'<div class="prog-profile-year-head">\' +\n          \'<span class="prog-profile-year-title">\' + year + \'年</span>\' +\n          \'<span class="prog-profile-year-total">投资总额<span class="yt-num">\' + total.toFixed(2) + \'亿</span>·\' + assets.length + \'类资产 · \' + detailRows.length + \'笔明细</span>\' +\n        \'</div>\' +\n        \'<table class="prog-profile-table">\' +\n          \'<thead><tr><th>资产类型</th><th class="num-col">规模(亿)</th><th class="num-col">占比</th><th class="num-col">平均利差</th></tr></thead>\' +\n          \'<tbody>\' + rowsHtml + \'</tbody>\' +\n        \'</table>\' + detailTable +\n      \'</div>\';\n    });\n    yearsHtml += \'<div class="prog-profile-source" style="margin-top:8px">利差口径：仅统计优先A/优先级/优先A1/优先A2（与发行定价·利差分析同步）· 规模含全部档位</div>\';\n    yearsHtml += \'</div>\';\n  } else {\n    yearsHtml = \'<div class="prog-profile-empty">暂无台账投资记录</div>\';\n  }\n  return yearsHtml;\n}\n\n// 构建授信统计HTML(独立section)\nfunction progBuildCredit(rec) {\n  let creditHtml = \'\';\n  let creditSource = \'\';\n  const creditKey = progMatchCredit(rec.name);\n  if (creditKey) {\n    const cd = PROG_CREDIT_DATA[creditKey];\n    creditHtml =\n      \'<div class="prog-profile-credit-item"><span class="label">授信总额</span><span class="val dyn">\' + cd.total + \'亿</span></div>\' +\n      \'<div class="prog-profile-credit-item"><span class="label">剩余授信</span><span class="val dyn">\' + cd.remain + \'亿</span></div>\';\n    creditSource = \'来源：授信总额度模块（20260630额度盘点）\';\n  } else if (rec.approval && rec.approval !== \'—\') {\n    creditHtml =\n      \'<div class="prog-profile-credit-item"><span class="label">批复情况</span><span class="val">\' + progEsc(rec.approval) + \'</span></div>\';\n    if (rec.quota && rec.quota !== \'—\') {\n      creditHtml += \'<div class="prog-profile-credit-item"><span class="label">额度使用</span><span class="val">\' + progEsc(rec.quota) + \'</span></div>\';\n    }\n    creditSource = \'来源：Joyspace 机构进展表（静态）\';\n  } else {\n    creditHtml = \'<div class="prog-profile-credit-item" style="color:#9aa5b5">暂无授信数据</div>\';\n  }\n  return \'<div class="prog-profile-credit">\' + creditHtml + \'</div>\' +\n    (creditSource ? \'<div class="prog-profile-source">\' + creditSource + \'</div>\' : \'\');\n}\n\n// 单个机构名 → 授信模块机构名(内部函数)\nfunction progMatchCreditSingle(name) {\n  if (PROG_CREDIT_DATA[name]) return name;\n  // 归一化映射(只映射真实属于18家的,不硬塞)\n  const norms = {\n    "工银理财": "工银理财",\n    "工商银行": "工银理财",\n    "建信理财": "建信理财",\n    "建设银行": "建设银行",\n    "交银理财": "交银理财",\n    "交通银行": "交银理财",\n    "民生理财": "民生理财",\n    "民生银行": "民生理财",\n    "光大理财": "光大理财",\n    "光大银行": "光大理财",\n    "华夏理财": "华夏理财",\n    "华夏银行": "华夏理财",\n    "广银理财": "广银理财",\n    "广发理财": "广银理财",\n    "江苏银行": "江苏银行",\n    "苏银理财": "江苏银行",\n    "南京银行": "南京银行",\n    "南银理财": "南银理财",\n    "杭银理财": "杭银理财",\n    "杭州银行": "杭银理财",\n    "杭州联合银行": "杭州联合银行",\n    "恒丰银行": "恒丰银行",\n    "恒丰理财": "恒丰银行",\n    "广州银行": "广州银行",\n    "沪农商行": "沪农商行",\n    "上海农商行": "沪农商行",\n    "上海农商": "沪农商行",\n    "北银理财": "北银理财",\n    "北京银行": "北银理财",\n    "东莞农商业银行": "东莞农商业银行",\n    "东莞农商": "东莞农商业银行",\n    "东莞银行": "东莞农商业银行",\n  };\n  if (norms[name] && PROG_CREDIT_DATA[norms[name]]) return norms[name];\n  // 模糊包含\n  for (const key of Object.keys(PROG_CREDIT_DATA)) {\n    if (name.indexOf(key) >= 0 || key.indexOf(name) >= 0) return key;\n  }\n  return null;\n}\n\n// 机构进展名 → 授信模块机构名匹配(支持 "/" 拆分)\nfunction progMatchCredit(progName) {\n  // 直接匹配\n  const direct = progMatchCreditSingle(progName);\n  if (direct) return direct;\n  // 拆分 "/" 前后,各自匹配\n  const parts = progName.split(\'/\').map(s => s.trim()).filter(Boolean);\n  if (parts.length > 1) {\n    for (const p of parts) {\n      const m = progMatchCreditSingle(p);\n      if (m) return m;  // 返回第一个匹配到的(通常是理财子)\n    }\n  }\n  return null;\n}\n\nfunction progEsc(s) {\n  if (!s) return \'\';\n  return String(s).replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\');\n}\n\n// 初始化（延迟执行，确保 DOM 就绪）\nsetTimeout(progInit, 100);\n'


def load_profile_data():
    if not DATA_PATH.exists():
        return []
    return json.loads(DATA_PATH.read_text(encoding="utf-8"))


def load_profile_meta():
    if not META_PATH.exists():
        return {}
    return json.loads(META_PATH.read_text(encoding="utf-8"))


def render_body(profile_data=None):
    data = load_profile_data() if profile_data is None else profile_data
    meta = load_profile_meta()
    snapshot = (meta.get('synced_at') or '2026-07-14')[:10]
    body = _BODY_HTML.replace('快照时间 2026-07-14', f'快照时间 {snapshot}')
    data_json = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    js = _PROFILE_JS_TEMPLATE.replace("__PROG_ALL_DATA__", data_json)
    return body + "\n<script>\n" + js + "\n</script>"
